globalThis.makeSubjectEdition = function (meta, rows) {
  const {subject, year, grade, contest, letters, tasksFile, answersFile, language} = meta;
  const folder = 'assets/' + subject + '/' + year + '/';
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(row => {
    const {title, question, choices, figure, figures, optionFigures, steps, context, audio, numericAnswer} = row;
    const condition = figures?.length ? {items: figures} : figure;
    const options = choices.map((text, i) => {
      const image = optionFigures?.[i];
      if (!image) return {text};
      return {text: row.showOptionText ? text : '', image: image.src,
        description: row.showOptionText ? text + '. ' + image.alt : image.alt,
        ...(image.detailSrc ? {detailSrc: image.detailSrc} : {}),
        pixelWidth: image.width, pixelHeight: image.height};
    });
    return {
      title, question, choices, language, context, guided: true, hideIntroText: true,
      skill: contest, answer: row.answer ?? null,
      points: row.points ?? meta.points,
      ...(row.acceptedAnswers ? {acceptedAnswers: row.acceptedAnswers} : {}),
      ...(row.adaptation ? {questionNote: row.adaptation} : {}),
      ...(row.number ? {number: row.number} : {}),
      ...(row.textAnswer !== undefined ? {textAnswer: row.textAnswer} : {}),
      ...(Number.isInteger(numericAnswer) ? {numericAnswer} : {}),
      ...(row.acceptedNumericAnswers ? {acceptedNumericAnswers: row.acceptedNumericAnswers} : {}),
      ...(audio ? {audio: folder + (meta.listeningFile ?? 'listening.mp3')} : {}),
      ...(condition || optionFigures ? {choiceLayout: {condition, options},
        choiceImages: options.map(option => option.image),
        ...(condition?.src ? {conditionImage: condition.src, conditionAlt: condition.alt} : {})} : {}),
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ...steps.map((explanation, index) => index === steps.length - 1
          ? ['Проверка', 'Проверка', explanation]
          : [index ? 'Шаг ' + (index + 1) : 'Первый шаг', 'Рассуждение', explanation]),
        ['Ответ', 'Ответ', ''],
      ],
    };
  });
  for (const group of meta.matchingGroups ?? []) {
    const parts = lessons.slice(group.start - 1, group.start - 1 + group.count);
    if (parts.length !== group.count || parts.some(part => !part.conditionImage ||
        JSON.stringify(part.choices) !== JSON.stringify(parts[0].choices))) throw new Error('Incomplete matching group ' + group.title);
    const steps = [
      ['Выбор', 'Условие задачи', ''],
      ...parts.map((part, index) => ['Рисунок ' + (index + (group.originalNumbers ? group.start : 1)), part.title,
        part.steps.slice(1, -1).map(step => step[2]).join(' ')]),
      ['Ответ', 'Все пары', ''],
    ];
    for (const part of parts) Object.assign(part, {matching: group, title: group.title, question: group.question, steps});
  }
  return {
    id: [year, subject, meta.session, grade, meta.editionSuffix].filter(Boolean).join('-'), year, grades,
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы') + (meta.sessionTitle ? ' · ' + meta.sessionTitle : '') + (meta.editionLabel ? ' · ' + meta.editionLabel : ''),
    ...(meta.sections ? {sections: meta.sections} : {}),
    ...(meta.titleLanguage ? {titleLanguage: meta.titleLanguage} : {}),
    subject, answerLetters: [...letters], sources: {
      contest, tasksUrl: folder + tasksFile, answersUrl: folder + answersFile,
      ...(meta.solutionsFile ? {solutionUrl: folder + meta.solutionsFile} : {}),
      ...(meta.reviewedKey ? {reviewedKey: true} : {}),
    },
    lessons, scenes: lessons.map(() => () => ''),
  };
};

const edition = globalThis.makeSubjectEdition({"subject":"kit","year":2015,"grade":"10-11","contest":"КИТ","letters":"АБВГ","count":26,"language":"ru","points":3,"tasksFile":"10-11.pdf","answersFile":"reviewed-10-11.pdf","sections":[{"start":1,"title":"Задания на 3 балла"},{"start":11,"title":"Задания на 4 балла"},{"start":21,"title":"Задания на 5 баллов"},{"start":24,"title":"Числовой ответ"}],"reviewedKey":true}, [{"number":1,"title":"Единица информации","question":"Какая из перечисленных единиц измерения информации наименьшая?","choices":["1 бит","1 байт","1 бот","1 баг"],"points":3,"steps":["Один бит может различать два состояния, например 0 и 1. В одном байте восемь битов.","«Бот» означает программу, а «баг» — ошибку. Из двух единиц информации меньше один бит."],"answer":0},{"number":2,"title":"Косточки на счётах","question":"Какое число отложено на счётах?","choices":["215","2015","8","2105"],"points":3,"steps":["Считаем косточки, сдвинутые влево. Ряд непосредственно над коротким четырёхкосточковым рядом показывает единицы: их пять.","Выше отложены один десяток, ноль сотен и две тысячи. Получается 2000 + 10 + 5 = 2015."],"answer":1,"figure":{"src":"assets/kit/2015/10-11-02.svg","alt":"Русские счёты. Считывай косточки, отделённые влево. Короткий ряд состоит из четырёх косточек.","width":286,"height":322}},{"number":3,"title":"Виды устройств","question":"Они бывают механические, оптические, лазерные, индукционные. Речь идёт о каких устройствах?","choices":["колонках","компьютерных мышах","мониторах","принтерах"],"points":3,"steps":["Перечислены разные способы отслеживания перемещения устройства. В механической модели вращается шарик, а оптическая отслеживает поверхность сенсором.","Так различаются компьютерные мыши. Оптическая и лазерная мыши выполняют ту же задачу перемещения указателя."],"answer":1},{"number":4,"title":"Деталь материнской платы","question":"Какой термин встречается в описании устройства материнской платы?","choices":["мост","эстакада","грот","шоссе"],"points":3,"steps":["Компоненты платы обмениваются данными через контроллеры. В традиционной схеме чипсета два таких узла называли северным и южным.","Общее слово в этих названиях — «мост». Оно указывает на соединение групп устройств."],"answer":0},{"number":5,"title":"Большой чертёж","question":"Что наиболее подходит для печати чертежей большого формата?","choices":["плоттер","3D-принтер","матричный принтер","печатная машинка"],"points":3,"steps":["Для чертежа нужны плоский лист большого формата и точное воспроизведение линий. 3D-принтер строит объёмный предмет.","Для вывода таких чертежей предназначен широкоформатный плоттер, или графопостроитель."],"answer":0},{"number":6,"title":"Два изображения","question":"Саша изменил один параметр изображения в графическом редакторе. Какой параметр он сильно уменьшил, чтобы из рисунка слева получить показанный справа?","choices":["яркость","глубину цвета","расширение","разрешение"],"points":3,"steps":["Справа вместо тонких деталей видны крупные квадратные ячейки. На ту же площадь приходится гораздо меньше отдельных отсчётов изображения.","Так проявляется снижение разрешения. Уменьшение глубины цвета сократило бы число оттенков, сохранив исходную сетку пикселей."],"answer":3,"figure":{"src":"assets/kit/2015/10-11-06.svg","alt":"Одно изображение кита с компьютером показано в двух вариантах. Слева хорошо различимы контуры, справа видны крупные квадратные ячейки.","width":408,"height":138}},{"number":7,"title":"Клавиши калькулятора","question":"Фёдор нажал по порядку [1], [2], [↑], [3], [×] и получил 36. Что получится при нажатии [3], [4], [↑], [7], [+]?","choices":["0","71","41","15"],"points":3,"steps":["Первый опыт показывает смысл стрелки: она разделяет ввод чисел. В память попало 12, затем введено 3 и выполнено умножение: 12 × 3 = 36.","Во втором опыте первым числом будет 34, вторым — 7. Нажатие плюса даст 34 + 7 = 41."],"answer":2},{"number":8,"title":"Сверхбольшая микросхема","question":"Почему схему называют сверхбольшой интегральной схемой (СБИС)?","choices":["весит более 10 кг","её габаритные размеры достигают 1 м","потребляет более 1000 кВт","включает в себя очень большое число логических элементов"],"points":3,"steps":["Степень интеграции показывает, сколько элементов размещено в одной микросхеме. Размер корпуса или его масса этого числа не определяют.","Слово «сверхбольшая» относится к числу интегрированных элементов. Современный кристалл может включать миллионы и миллиарды транзисторов."],"answer":3,"adaptation":"Число элементов зависит от поколения микросхемы. Уточнён общий смысл степени интеграции."},{"number":9,"title":"Имена и языки","question":"Кто из перечисленных людей не является разработчиком языка программирования?","choices":["Б. Паскаль","Б. Страуструп","Дж. Бэкус","Н. Вирт"],"points":3,"steps":["Бьёрн Страуструп создал C++, Джон Бэкус руководил разработкой Fortran, а Никлаус Вирт создал Pascal.","Блез Паскаль жил в XVII веке и построил механическую счётную машину. Язык Pascal назвали в его честь гораздо позднее."],"answer":0},{"number":10,"title":"Форматы файлов","question":"Какое из обозначений не является форматом графического файла?","choices":["gif","php","jpg","png"],"points":3,"steps":["GIF, JPEG (расширение .jpg) и PNG задают способы хранения изображений.","PHP — язык программирования, а .php обычно обозначает файл с программным кодом."],"answer":1},{"number":11,"title":"Фраза для проверки шрифта","question":"Какую строку используют как панграмму для демонстрации кириллического шрифта?","choices":["Каждый охотник желает знать, где сидит фазан.","Оба фазана жёлтой краской мазаны (рядом надутые сидят).","Цыган на цыпочках цыплёнку цыкнул: «Цыц».","Съешь ещё этих мягких французских булок, да выпей же чаю."],"points":4,"steps":["Задача панграммы — показать все буквы алфавита. Первая фраза помогает запомнить цвета радуги, а третья — написание «ы» после «ц».","Фраза про мягкие французские булки охватывает весь русский алфавит. В ней встречаются даже «ъ», «ё» и «щ»."],"answer":3},{"number":12,"title":"Поездка вчетвером","question":"Четверо друзей платили за мероприятия по очереди. Завтрак оплатила Маша, цена 33, участвовали Маша, Коля, Даша. Экскурсию оплатил Коля, цена 40, участвовали Коля и Паша. Обед оплатила Даша, цена 56, участвовали все четверо. Ужин оплатил Паша, цена 48, участвовали Маша, Коля и Паша. Затраты на каждое мероприятие делят поровну между его участниками. Кто должен больше всего доплатить?","choices":["Маша","Коля","Даша","Паша"],"points":4,"steps":["Доля одного участника за завтрак — 11, за экскурсию — 20, за обед — 14, за ужин — 16. Коля был на всех четырёх: его расходы составили 61, а внёс он 40. Он должен ещё 21.","Маша должна 11 + 14 + 16 − 33 = 8, Паша — 20 + 14 + 16 − 48 = 2. Даша внесла больше своей доли. Самая большая доплата у Коли."],"answer":1},{"number":13,"title":"Симметрия на часах","question":"Назовём время счастливым, если оно читается одинаково слева направо и справа налево. Сейчас 20:02. Сколько минут прошло с предыдущего счастливого времени?","choices":["51","251","651","1062"],"points":4,"steps":["Минуты должны повторять цифры часов в обратном порядке. Для 19, 18, 17 и 16 получились бы 91, 81, 71 и 61 минута, что невозможно. Для 15 подходят 51 минута.","С 15:51 до 16:00 прошло 9 минут, дальше до 20:00 — 240, ещё 2 минуты — до 20:02. Всего 251 минута."],"answer":1},{"number":14,"title":"Редактирование котом","question":"Кот набрал строку. Знайка поставил курсор в конец и выполнил команды: влево, влево, Backspace, влево, пробел, влево, влево, пробел, влево, влево, влево, Delete. Получилось «кит и кот». Какая строка была вначале? Backspace удаляет символ слева от курсора, Delete — справа.","choices":["ткитикрот","кит и крот","кити крот","киттикрот"],"points":4,"steps":["Проверь строку «киттикрот». Два движения влево ставят курсор перед «от», Backspace стирает «р». После следующего движения влево курсор оказывается перед «кот», и пробел отделяет это слово.","Ещё два движения влево и пробел отделяют «и». Три движения влево и Delete удаляют одну из соседних «т». Осталась строка «кит и кот»."],"answer":3},{"number":15,"title":"Модели баз данных","question":"Какого названия нет в стандартном перечне классических моделей данных наряду с сетевой, реляционной и иерархической?","choices":["субъектная","реляционная","сетевая","иерархическая"],"points":4,"steps":["Иерархическая модель организует записи как дерево, сетевая допускает сеть связей, а реляционная представляет данные в отношениях (таблицах).","«Субъектная» в этот перечень трёх классических моделей данных не входит."],"answer":0,"adaptation":"Проверяются классические модели данных, перечисляемые в школьном курсе."},{"number":16,"title":"Слова в алфавитном порядке","question":"Расположим по алфавиту десять русских названий цифр. Возьмём четыре последних слова и составим из соответствующих цифр наибольшее трёхзначное число без повторений. Какое это число?","choices":["987","764","643","346"],"points":4,"steps":["В конце списка стоят «семь», «три», «четыре», «шесть». Они начинаются на с, т, ч, ш и следуют после остальных слов. Получены цифры 7, 3, 4, 6.","Ставим самую большую цифру в сотни, следующую в десятки и ещё одну в единицы: 7, затем 6 и 4. Получается 764."],"answer":1},{"number":17,"title":"Сетевые обозначения","question":"Какое из перечисленных обозначений не является названием протокола передачи данных?","choices":["HTTP","WWW","FTP","IP"],"points":4,"steps":["HTTP описывает обмен веб-сообщениями, FTP — передачу файлов, а IP — доставку пакетов по сети.","WWW означает World Wide Web, Всемирную паутину. Она использует протоколы, в частности HTTP."],"answer":1},{"number":18,"title":"Имя в телефоне","question":"При поиске контакта с помощью Т9 Маша ввела 2454539. Одну лишнюю клавишу она нажала по ошибке. Какое имя она искала? Группы букв показаны на клавиатуре.","choices":["Володя","Алексей","Марина","Виктор"],"points":4,"steps":["Одна клавиша кодирует любую букву из подписанной на ней группы. «Володя» даёт В→2, О→5, Л→4, О→5, Д→3, Я→9: это 254539.","Из набора 2454539 достаточно удалить вторую цифру 4, чтобы осталось 254539. Остальные имена так не кодируются."],"answer":0,"adaptation":"Уточнено, что ошибочное нажатие было лишним.","figure":{"src":"assets/kit/2015/10-11-18.svg","alt":"Телефонная клавиатура Т9 с русскими буквами. 2 — АБВГ, 3 — ДЕЖЗ, 4 — ИЙКЛ, 5 — МНОП, 6 — РСТУ, 7 — ФХЦЧ, 8 — ШЩЪЫ, 9 — ЬЭЮЯ.","width":316,"height":183}},{"number":19,"title":"Значки планшета","question":"На планшете помещаются четыре значка вдоль короткой стороны экрана и пять вдоль длинной. Значки нумеруются по строкам слева направо, сверху вниз. В вертикальной ориентации значок находится в строке 3, столбце 4. Где он будет после поворота экрана, если порядок значков сохраняется?","choices":["3–2","2–5","4–3","3–4"],"points":4,"steps":["В вертикальной ориентации до третьей строки идут 2 × 4 = 8 значков. Нужный стоит четвёртым и имеет номер 12.","При пяти значках в строке первые десять занимают две строки. Двенадцатый становится вторым в третьей строке, то есть 3–2."],"answer":0,"figure":{"src":"assets/kit/2015/10-11-19.svg","alt":"Планшет в вертикальной ориентации: пять рядов по четыре значка в каждом.","width":186,"height":211}},{"number":20,"title":"Маршрут экспедитора","question":"Экспедитор выходит из A и возвращается в A. Нужно побывать в B, C и D в любом порядке. Рёбра на схеме двусторонние, числа обозначают время. За какое наименьшее время можно пройти маршрут?","choices":["5","6","7","8"],"points":4,"steps":["Можно пойти A–B–C–D–C–B–A. Каждое из шести рёбер этого маршрута стоит 1, значит, шести единиц времени достаточно.","Самый быстрый путь из A в D стоит 3: через C — 2 + 1, через B и C — 1 + 1 + 1. На обратный путь нужно ещё хотя бы 3. Более короткий обход невозможен."],"answer":1,"figure":{"src":"assets/kit/2015/10-11-20.svg","alt":"Схема дорог: AB — 1, AC — 2, AD — 5, AE — 3, BC — 1, BD — 3, CD — 1, CE — 1, DE — 1.","width":290,"height":205}},{"number":21,"title":"Часы заполняют экран","question":"Четыре цифры высотой шесть клеток строятся построчно, сдвигаясь справа налево. Внутри каждой строки расстояния между закрашенными клетками сохраняются. Первая строка уже остановилась. Какое время покажут часы на рисунке?","choices":["01:45","04:46","21:34","22:53"],"points":5,"steps":["Оставь верхнюю строку на месте. Сдвинь вторую строку на 3 клетки влево, третью и четвёртую на 4 клетки, пятую на 6, а шестую на 8.","Прочитай получившиеся цифры слева направо. Первые две образуют 01, последние две образуют 45. Часы показывают 01:45."],"answer":0,"figure":{"src":"assets/kit/2015/10-11-21.svg","alt":"Экран формирующихся часов в клетках. Верхняя из шести строк уже остановилась, остальные сдвигаются.","width":348,"height":109}},{"number":22,"title":"Способы ввода пароля","question":"Аскар разрешает трёхзначный код на клавиатуре из десяти цифр: в том числе начиная с нуля, цифры могут повторяться. Графический ключ Артёма обходит каждую вершину схемы ровно один раз, в любом порядке. Для какой из четырёх схем число ключей ближе всего к числу цифровых кодов?","choices":["Четыре вершины","Пять вершин","Шесть вершин","Семь вершин"],"points":5,"steps":["Цифровых кодов 10 × 10 × 10 = 1000. Для схемы с n вершинами возможны n! порядков обхода. Для четырёх, пяти, шести и семи вершин это 24, 120, 720 и 5040.","Ближайшее к 1000 значение — 720: разница лишь 280. Значит, подходит схема с шестью вершинами."],"answer":2,"adaptation":"Уточнены правила составления кода и обхода точек.","optionFigures":[{"src":"assets/kit/2015/10-11-22-a.svg","alt":"Схема из 4 вершин.","width":128,"height":128},{"src":"assets/kit/2015/10-11-22-b.svg","alt":"Схема из 5 вершин.","width":128,"height":128},{"src":"assets/kit/2015/10-11-22-c.svg","alt":"Схема из 6 вершин.","width":128,"height":128},{"src":"assets/kit/2015/10-11-22-d.svg","alt":"Схема из 7 вершин.","width":128,"height":128}]},{"number":23,"title":"Стеклянные стены","question":"Этаж имеет размер 6 × 6 клеток. Верхняя и нижняя стены стеклянные, боковые — бетонные. Комната занимает одну из фигур, показанных на схеме. Фигуры можно поворачивать и использовать повторно. Каждая комната должна стороной клетки примыкать к стеклянной стене. Неиспользованные клетки становятся техническим помещением. Сколько комнат можно разместить самое большее?","choices":["6","8","9","10"],"points":5,"steps":["У каждой фигуры четыре клетки, а её глубина не больше трёх. Поэтому комнаты у верхней стены целиком входят в верхние три ряда, а комнаты у нижней — в нижние три. В каждой половине 18 клеток. Там помещается не более четырёх комнат, всего не более восьми.","Восемь достижимы. Пример плана по строкам: A·BBCD / AABCCD / A·BCDD / EEFG·H / EFFGHH / E·FGGH. Одна буква обозначает одну комнату, точка — свободную клетку."],"answer":1,"adaptation":"Уточнены правила размещения и поворота фигур.","figure":{"src":"assets/kit/2015/10-11-23.svg","alt":"Квадратный этаж шесть на шесть клеток. Стеклянные стены сверху и снизу. Рядом показаны пять разрешённых фигур из четырёх клеток.","width":338,"height":172}},{"number":24,"title":"Число на входе","question":"Какое число ввёл пользователь, если программа напечатала 100? Программа на Pascal:\nvar a: array [1..8] of integer;\n    i, sum: integer;\nbegin\n  Readln(a[1]);\n  sum := 0;\n  for i := 2 to 8 do\n    a[i] := a[i-1]+3;\n  for i := 8 downto 1 do\n    sum := sum+a[i];\n  writeln(sum);\nend.","choices":[],"points":5,"steps":["Обозначим введённое число x. Массив заполняется числами x, x + 3, …, x + 21. Второй цикл складывает их все, начиная с последнего.","Сумма равна 8x + 3 × (0 + 1 + … + 7) = 8x + 84. Из 8x + 84 = 100 получаем x = 2."],"numericAnswer":2},{"number":25,"title":"Цвет последней полосы","question":"Изображение имеет ширину 800 пикселей. Справа налево цветные полосы занимают 1, 2, 4, 8, … столбцов. Цвет правой полосы — 1055BB, следующей — 1055B7 в шестнадцатеричной записи RGB. При каждом шаге значение цвета уменьшается на 4. Чему равно целое значение цвета крайней левой полосы по модулю 16? Ответ запиши в десятичной системе.","choices":[],"points":5,"steps":["Первые девять полос занимают 1 + 2 + 4 + … + 256 = 511 столбцов. В крайней левой точке уже идёт десятая полоса. Её цвет уменьшился на 9 × 4 = 36.","Для остатка по модулю 16 важна только последняя цифра. В исходном цвете это B, то есть 11. У числа 11 − 36 = −25 остаток при делении на 16 равен 7."],"numericAnswer":7},{"number":26,"title":"Цифра в трёх основаниях","question":"Дана сумма (K72FE0360J#4)₃₅ + (134HDF23#3GF0023G)₃₄ + (#1038GA74BF6)₃₃. Знаком # во всех трёх числах обозначена одна и та же цифра. При каком её десятичном значении сумма будет наибольшим возможным нечётным числом? После 9 цифры обозначаются латинскими буквами A, B, … по порядку.","choices":[],"points":5,"steps":["Общая цифра должна быть допустима даже в основании 33. Поэтому она не превосходит 32. Все коэффициенты при этой цифре положительны, значит, сумма растёт вместе с ней.","Проверим 32. У числа в чётном основании 34 чётность задаёт последняя цифра G = 16, так что оно чётное. В нечётных основаниях чётность числа равна чётности суммы его цифр: у первого и третьего чисел при # = 32 она различна. Вся сумма нечётна, и максимальная цифра 32 подходит."],"numericAnswer":32}]);
